<?php
namespace Modules\Glitter\Workflow\Listeners;
use App\ActivityLog\Traits\ResolvesActivityLogType; use App\Contracts\Extension\HookListenerInterface; use Modules\Glitter\Workflow\Models\Workflow;
class WorkflowActivityLogListener implements HookListenerInterface { use ResolvesActivityLogType; public static function getSubscribedHooks():array{return ['glitter-workflow.workflow.after_create'=>['method'=>'create','priority'=>20],'glitter-workflow.workflow.after_update'=>['method'=>'update','priority'=>20],'glitter-workflow.workflow.after_delete'=>['method'=>'delete','priority'=>20],'glitter-workflow.workflow.after_activate'=>['method'=>'activate','priority'=>20],'glitter-workflow.workflow.after_deactivate'=>['method'=>'deactivate','priority'=>20]];} public function handle(...$args):void{} private function write(string $a,Workflow $w):void{$this->logActivity('workflow.'.$a,['loggable'=>$w,'description_key'=>'glitter-workflow::activity_log.'.$a,'description_params'=>['name'=>$w->name],'properties'=>['uuid'=>$w->uuid,'version'=>$w->version,'is_active'=>$w->is_active]]);} public function create(Workflow $w):void{$this->write('create',$w);} public function update(Workflow $w):void{$this->write('update',$w);} public function delete(Workflow $w):void{$this->write('delete',$w);} public function activate(Workflow $w):void{$this->write('activate',$w);} public function deactivate(Workflow $w):void{$this->write('deactivate',$w);} }
